WITH with_gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 15 MINUTES THEN 1 ELSE 0 END AS new_group_flag FROM device_readings), sessionized AS (SELECT id, device_code, reading_ts, pressure, status_bits, firmware, SUM(new_group_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT CASE WHEN burst_id >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END AS burst_id_tier, COUNT(CASE WHEN device_code = 'DV-03' THEN 1 END) AS dv_03_count, ROUND(SUM(burst_id) / NULLIF(COUNT(CASE WHEN device_code = 'DV-03' THEN 1 END), 0), 2) AS burst_id_per_dv_03, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS span_minutes, ROUND(AVG(burst_id), 2) AS avg_burst_id, ROUND(AVG(status_bits), 2) AS avg_status_bits FROM sessionized GROUP BY CASE WHEN burst_id >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY avg_status_bits NULLS LAST
